/**
 * Deret Sales Growth mengikuti waterfall di desk (CoreAnalytics.js):
 * hanya bulan sampai bulan berjalan yang dihitung, bulan pertama yang berdata
 * memakai nilai pencairannya, bulan berikutnya memakai pertumbuhan terhadap
 * bulan sebelumnya, dan kolom terakhir adalah akumulasi setahun.
 *
 * Bedanya untuk ponsel: skala tinggi batang MURNI dari persentase, sehingga
 * pertumbuhan kecil tetap terbaca. Dua kolom bernilai rupiah digambar sebagai
 * penanda berukuran tetap, bukan bagian dari skala itu.
 */
const growthSeries = computed(() => {
	const months = growthMonths.value
	const bulanBerjalan = now.getMonth() + 1
	const amounts = []
	for (let i = 0; i < 12; i++) {
		const md = months[i] || {}
		amounts.push(md.amount != null && i + 1 <= bulanBerjalan ? Number(md.amount) : null)
	}
	const totalAcc = amounts.reduce((sum, a) => sum + (a || 0), 0)

	const kolom = []
	let sudahAdaAwal = false
	for (let i = 0; i < 12; i++) {
		const amt = amounts[i]
		const dasar = { key: `m${i}`, month: BULAN_SINGKAT[i] }
		if (amt === null) {
			kolom.push({ ...dasar, kind: 'kosong', label: '' })
			continue
		}
		const prev = i > 0 ? amounts[i - 1] : null
		if (!sudahAdaAwal || prev === null || !(prev > 0)) {
			sudahAdaAwal = true
			kolom.push({
				...dasar,
				kind: 'amount',
				color: '#4F52E5',
				label: rupiahRingkas(amt),
				labelClass: 'text-ui-metric-indigo',
			})
			continue
		}
		const pctGrowth = ((amt - prev) / prev) * 100
		kolom.push({
			...dasar,
			kind: 'growth',
			pct: pctGrowth,
			label: delta(pctGrowth),
			labelClass: pctGrowth >= 0 ? 'text-ui-metric-up' : 'text-ui-metric-down',
		})
	}

	kolom.push({
		key: 'total',
		month: 'Total',
		kind: 'amount',
		color: '#1e2a52',
		label: rupiahRingkas(totalAcc),
		labelClass: 'text-ui-heading',
	})

	const maxAbs = Math.max(
		1,
		...kolom.filter((k) => k.kind === 'growth').map((k) => Math.abs(k.pct)),
	)
	return kolom.map((k) =>
		k.kind === 'growth'
			? { ...k, height: `${Math.min(100, (Math.abs(k.pct) / maxAbs) * 100)}%` }
			: k,
	)
})

// Donut: tiap potong sebanding realisasi cabangnya, urut & berwarna sama dengan desk.
const donutSegments = computed(() => {
	const rows = leaderboardCabang.value
	const total = rows.reduce((sum, r) => sum + (Number(r.realisasi_amount) || 0), 0)
	if (!total) return []
	// Celah antar potong; potongan tipis tetap disisakan agar tidak hilang.
	const GAP = 2.5
	let acc = 0
	return rows.map((r, i) => {
		const frac = (Number(r.realisasi_amount) || 0) / total
		const seg = {
			cabang: r.cabang,
			share: frac * 100,
			color: donutColor(i),
			dash: Math.max(0.6, frac * DONUT_C - GAP),
			offset: -acc * DONUT_C,
		}
		acc += frac
		return seg
	})
})

// Potongan yang diterangkan di pusat donut: yang sedang dipilih, atau yang
// terbesar bila belum ada yang dipilih.
const sorotan = computed(() => {
	const segs = donutSegments.value
	if (!segs.length) return { cabang: '—', share: null, color: '#94a3b8' }
	const dipilih = segs.find((seg) => seg.cabang === activeCabang.value)
	return dipilih || segs.reduce((a, b) => (b.share > a.share ? b : a))
})

/** Versi lembut sebuah warna heks, untuk latar chip legenda. */
function softColor(hex, alpha = 0.14) {
	const h = String(hex).replace('#', '')
	const n = parseInt(h.length === 3 ? h.replace(/./g, (c) => c + c) : h, 16)
	// eslint-disable-next-line no-bitwise
	return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`
}

function donutColor(i) {
	return DONUT_PALETTE[i % DONUT_PALETTE.length]
}

function cabangAchievement(row) {
	return ratioPct(row.realisasi_amount, row.target_amount, row.achievement_pct)
}

const grandTotalCabang = computed(() => {
	const rows = leaderboardCabang.value
	const jumlah = (field) => rows.reduce((sum, r) => sum + (Number(r[field]) || 0), 0)
	const realisasi = jumlah('realisasi_amount')
	const target = jumlah('target_amount')
	const prev = jumlah('prev_amount')
	return {
		realisasi_amount: realisasi,
		target_amount: target,
		realisasi_unit: jumlah('realisasi_unit'),
		achievement_pct: target ? (realisasi / target) * 100 : null,
		growth_pct: prev ? ((realisasi - prev) / prev) * 100 : null,
	}
})

/** Angka besar di pojok kanan atas, sepadan OVR — pencapaian dibulatkan. */
function futRating(achievement) {
	const p = Number(achievement)
	if (!Number.isFinite(p)) return '—'
	return fmtNum(Math.round(p), 0)
}

// Foto kartu diambil dari doctype User lewat endpoint portal; email CMO-nya
// sudah ada di baris leaderboard. Yang tidak punya foto tidak dikembalikan
// server, jadi ketiadaan kunci = pakai inisial.
const cmoPhotos = ref({})
const fotoGagal = reactive({})

function fotoCmo(row) {
	const url = cmoPhotos.value[row.marketing]
	if (!url || fotoGagal[row.marketing]) return ''

	// URL absolut (mis. gravatar) dipakai apa adanya.
	if (!url.startsWith('/')) return url

	// Berkas yang dilayani Frappe sendiri dilewatkan endpoint portal: foto
	// profil biasanya PRIVATE dan dilampirkan ke record User orang lain, jadi
	// /private/files/... membalas 403 untuk hampir semua pemakai dashboard.
	const src = `/api/method/${API_FOTO_FILE}?email=${encodeURIComponent(row.marketing)}`
	// Bundel native berjalan dari origin lokal, jadi path relatif harus
	// ditempeli host backend.
	return isNativeApp() ? API_BASE + src : src
}

async function loadFotoCmo() {
	const emails = leaderboardCmo.value.map((r) => r.marketing).filter(Boolean)
	Object.keys(fotoGagal).forEach((k) => delete fotoGagal[k])
	if (!emails.length) {
		cmoPhotos.value = {}
		return
	}
	try {
		cmoPhotos.value = (await call(API_FOTO, { emails: JSON.stringify(emails) })) || {}
	} catch {
		// Foto sekadar pemanis; kegagalannya cukup berarti kartu memakai inisial.
		cmoPhotos.value = {}
	}
}

// Penanda "ke berapa dari berapa" di sudut kanan judul.
const cmoTrack = ref(null)
const cmoAktif = ref(0)

function onCmoScroll() {
	const el = cmoTrack.value
	if (!el) return
	const tengah = el.scrollLeft + el.clientWidth / 2
	let terdekat = 0
	let jarakTerdekat = Infinity
	;[...el.children].forEach((anak, i) => {
		const jarak = Math.abs(anak.offsetLeft + anak.offsetWidth / 2 - tengah)
		if (jarak < jarakTerdekat) {
			jarakTerdekat = jarak
			terdekat = i
		}
	})
	cmoAktif.value = terdekat
}

// Pencapaian CMO diturunkan dari dua kolom leaderboard yang sama dengan desk.
function cmoAchievement(row) {
	const target = Number(row.target_marketing) || 0
	if (!target) return null
	return ((Number(row.realisasi_unit) || 0) / target) * 100
}

// Skala batang chart dihitung dari nilai terbesar yang tampil, jadi bentuknya
// tetap terbaca berapa pun besaran angkanya.
const maxActualTarget = computed(() =>
	Math.max(
		1,
		...actualVsTarget.value.flatMap((m) => [Number(m.realisasi) || 0, Number(m.target) || 0]),
	),
)

function barHeight(value, max) {
	const v = Math.max(0, Number(value) || 0)
	return `${Math.min(100, (v / max) * 100)}%`
}

/**
 * Persentase dari dua angka mentahnya. Server sudah membulatkan sebagian
 * persentase ke 1 desimal; menghitung ulang dari pembilang & penyebut yang ikut
 * dikirim membuat 2 angka di belakang koma benar-benar berarti, bukan nol
 * tempelan. `fallback` dipakai saat penyebutnya nol atau tidak dikirim.
 */
function ratioPct(num, den, fallback = null) {
	const d = Number(den) || 0
	if (!d) return fallback ?? null
	return ((Number(num) || 0) / d) * 100
}

/** Porsi satu seri di dalam kelompoknya, untuk lebar batang bertumpuk. */
function sharePct(value, total) {
	const t = Number(total) || 0
	if (!t) return 0
	return (Math.max(0, Number(value) || 0) / t) * 100
}

// ---- Format ----------------------------------------------------------------
function int(value) {
	if (value === null || value === undefined) return '—'
	return fmtNum(value, 0)
}

/** Rupiah utuh dengan pemisah ribuan — dipakai di semua angka nominal. */
function rupiahFull(value) {
	if (value === null || value === undefined) return '—'
	const n = Number(value) || 0
	return `${n < 0 ? '-' : ''}Rp ${fmtNum(Math.abs(n), 0)}`
}

/** Bentuk ringkas 2 desimal, dipakai hanya di label chart yang sempit. */
function rupiahRingkas(value) {
	if (value === null || value === undefined) return '—'
	const n = Number(value) || 0
	const abs = Math.abs(n)
	const sign = n < 0 ? '-' : ''
	if (abs >= 1e12) return `${sign}Rp ${fmtNum(abs / 1e12, 2)} T`
	if (abs >= 1e9) return `${sign}Rp ${fmtNum(abs / 1e9, 2)} M`
	if (abs >= 1e6) return `${sign}Rp ${fmtNum(abs / 1e6, 2)} Jt`
	if (abs >= 1e3) return `${sign}Rp ${fmtNum(abs / 1e3, 2)} rb`
	return `${sign}Rp ${fmtNum(abs, 0)}`
}

// Seluruh persentase memakai 2 angka di belakang koma. Sebagian nilai sudah
// dibulatkan ke 1 desimal oleh server; yang ditambah di sini hanya cara
// menuliskannya, bukan ketelitian angkanya.
function pct(value) {
	if (value === null || value === undefined) return 'n/a'
	return `${fmtNumFixed(value, 2)}%`
}

function delta(value) {
	if (value === null || value === undefined) return 'n/a'
	const n = Number(value)
	if (!Number.isFinite(n)) return 'n/a'
	return `${n > 0 ? '+' : ''}${fmtNumFixed(n, 2)}%`
}

function durasi(d) {
	if (!d || d.nilai === null || d.nilai === undefined) return '—'
	return `${fmtNum(d.nilai, 2)} ${d.satuan || ''}`.trim()
}

function pctBadgeClass(value) {
	if (value === null || value === undefined) return 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
	const p = Number(value) || 0
	if (p < 85) return 'bg-ui-surface-red-50 text-ui-ink-red-600'
	if (p < 97) return 'bg-ui-surface-amber-50 text-ui-ink-amber-600'
	return 'bg-ui-surface-green-50 text-ui-ink-green-600'
}

// TAT lebih cepat itu BAIK, jadi warnanya dibalik lewat `lebihKecilLebihBaik`.
function deltaPillClass(value, lebihKecilLebihBaik = false) {
	const n = Number(value)
	if (!Number.isFinite(n)) return 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
	const baik = lebihKecilLebihBaik ? n <= 0 : n >= 0
	return baik
		? 'bg-ui-surface-green-50 text-ui-ink-green-600'
		: 'bg-ui-surface-red-50 text-ui-ink-red-600'
}

function deltaChipClass(value) {
	const n = Number(value)
	if (!Number.isFinite(n)) return 'bg-white/15 text-white/80'
	return n >= 0
		? 'bg-ui-surface-green-400/20 text-ui-ink-green-200'
		: 'bg-ui-surface-red-400/20 text-ui-ink-red-200'
}

// Latar solid supaya lencananya benar-benar terbaca sebagai penanda, bukan
// sekadar teks berwarna. TAT makin kecil makin baik.
function tatDeltaColor(value) {
	const n = Number(value)
	if (!Number.isFinite(n)) return '#94a3b8'
	return n <= 0 ? '#0f9d63' : '#dc2626'
}

function rankClass(idx) {
	if (idx === 0) return 'bg-ui-surface-amber-100 text-ui-ink-amber-700'
	if (idx === 1) return 'bg-ui-surface-gray-200 text-ui-ink-gray-700'
	if (idx === 2) return 'bg-ui-surface-orange-100 text-ui-ink-orange-700'
	return 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
}

// ---- Aksi ------------------------------------------------------------------
function openFilter() {
	Object.assign(draft, filters)
	showFilter.value = true
}

function resetFilter() {
	draft.cabang = 'ALL'
	draft.bulan = now.getMonth() + 1
	draft.tahun = now.getFullYear()
}

function applyFilter() {
	filters.cabang = draft.cabang
	filters.bulan = draft.bulan
	filters.tahun = draft.tahun
	if (
		filters.cabang === 'ALL' &&
		filters.bulan === now.getMonth() + 1 &&
		filters.tahun === now.getFullYear()
	) {
		listPersistence.clearSession()
	} else {
		listPersistence.writeSession({
			filters: { cabang: filters.cabang, bulan: filters.bulan, tahun: filters.tahun },
		})
	}
	showFilter.value = false
	loadAll()
}

// Ganti tab demografi cukup memanggil endpoint demografinya saja — memuat ulang
// seluruh bundel hanya untuk satu daftar itu boros di jaringan ponsel.
async function selectTab(key) {
	if (filters.tab === key) return
	filters.tab = key
	loadingTab.value = true
	try {
		const args = { cabang: filters.cabang, bulan: filters.bulan, tahun: filters.tahun }
		if (key === 'audience') {
			audience.value = await call(API_AUDIENCE, args)
			return
		}
		const data = await call(API_DEMOGRAPHICS, { ...args, dimension: key })
		if (dash.value) {
			dash.value.demographics = {
				active_tab: key,
				total: data?.total || 0,
				buckets: data?.buckets || [],
			}
		}
	} catch (e) {
		notifyError(e, 'Gagal memuat demografi')
	} finally {
		loadingTab.value = false
	}
}

async function loadAll() {
	loading.value = true
	cmoAktif.value = 0
	dealerExpanded.value = false
	cabangDetail.value = false
	activeCabang.value = null
	try {
		const args = { cabang: filters.cabang, bulan: filters.bulan, tahun: filters.tahun }
		dash.value = await call(API_DASHBOARD, {
			...args,
			tab: filters.tab === 'audience' ? 'status_rumah' : filters.tab,
		})
		fatalError.value = ''

		// Proyeksi WAJIB dipanggil setelah bundel: R (Sales Amount) adalah
		// masukan rumusnya dan tidak dihitung sendiri oleh endpointnya. Tanpa
		// dikirim, R jadi 0 dan ketiga skenario meleset dari angka di desk.
		// `bypass_cache` ikut dikirim karena kunci cache-nya tidak memuat R —
		// sama persis dengan yang dilakukan ProyeksiSection.js.
		loadProyeksi(args)
		loadFotoCmo()

		// Tab audience tidak ikut dalam bundel, jadi disegarkan terpisah saat
		// sedang aktif — kalau tidak, angkanya tertinggal di filter sebelumnya.
		if (filters.tab === 'audience') {
			audience.value = await call(API_AUDIENCE, args)
		}
	} catch (e) {
		if (!dash.value) fatalError.value = errorText(e)
		else notifyError(e, 'Gagal memuat Sales Dashboard')
	} finally {
		loading.value = false
	}
}

// Kegagalan proyeksi tidak boleh menjatuhkan seluruh halaman, jadi ditangani
// terpisah dan hanya menyembunyikan kartunya.
async function loadProyeksi(args) {
	try {
		proyeksi.value = await call(API_PROYEKSI, {
			...args,
			realisasi_amount: Number(card1.value.realisasi_amount) || 0,
		})
	} catch {
		proyeksi.value = null
	}
}

async function reload() {
	if (loading.value) return
	await loadAll()
}

// Pesan Frappe datang sebagai `messages` (list HTML) atau `message`.
function errorText(e) {
	const raw = e?.messages?.join(' ') || e?.message || ''
	const text = String(raw)
		.replace(/<[^>]*>/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
	return text || 'Anda tidak punya akses ke dashboard ini.'
}

onMounted(async () => {
	await refreshCsrfToken()
	const saved = listPersistence.readSession({
		filters: { cabang: 'ALL', bulan: now.getMonth() + 1, tahun: now.getFullYear() },
	}).filters
	filters.cabang = saved.cabang
	if (saved.bulan >= 1 && saved.bulan <= 12) filters.bulan = saved.bulan
	if (saved.tahun >= 2000 && saved.tahun <= now.getFullYear() + 1) filters.tahun = saved.tahun
	await loadAll()
	const branches = [
		'ALL',
		...branchOptions.value.map((option) =>
			typeof option === 'string' ? option : option.value,
		),
	]
	if (dash.value?.scope?.locked_cabang) filters.cabang = dash.value.scope.locked_cabang
	else if (!branches.includes(filters.cabang)) {
		filters.cabang = 'ALL'
		listPersistence.writeSession({
			filters: { cabang: filters.cabang, bulan: filters.bulan, tahun: filters.tahun },
		})
	}
})
</script>

